import os
import json
from flask import Flask, request, jsonify
from openai import OpenAI
from exa_py import Exa

app = Flask(__name__, static_folder=".", static_url_path="")

exa = Exa("c3279e9c-b469-43a0-92a9-1bbe730e8280")

client = OpenAI(
    api_key=os.environ["REQUESTY_API_KEY"],
    base_url="",
)

EXA_TOOL = {
    "type": "function",
    "function": {
        "name": "exa_search",
        "description": "Search the web for real-time information. Call this whenever you need current or factual information.",
        "parameters": {
            "type": "object",
            "required": ["query", "search_type", "summary_query"],
            "properties": {
                "query": {"type": "string", "description": "The search query"},
                "search_type": {
                    "type": "string",
                    "enum": ["auto", "instant", "fast", "deep-lite", "deep", "deep-reasoning"],
                    "description": "Search type: instant=~250ms, fast=~450ms, auto=~1s, deep-lite=4s, deep=4-15s, deep-reasoning=12-40s"
                },
                "summary_query": {"type": "string", "description": "A focused prompt for summarizing each result"},
                "include_domains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Domains to include"
                },
                "exclude_domains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Domains to exclude"
                }
            }
        }
    }
}


def run_exa_search(query, search_type, summary_query, include_domains=None, exclude_domains=None):
    kwargs = {
        "num_results": 100,
        "type": search_type,
        "contents": {"summary": {"query": summary_query}}
    }
    if include_domains:
        kwargs["include_domains"] = include_domains
    if exclude_domains:
        kwargs["exclude_domains"] = exclude_domains
    result = exa.search(query, **kwargs)
    return [
        {
            "id": r.id,
            "url": r.url,
            "title": r.title,
            "published_date": r.published_date,
            "author": r.author,
            "score": r.score,
            "summary": r.summary
        }
        for r in result.results
    ]


@app.route("/")
def index():
    return app.send_static_file("index.html")


@app.route("/chat", methods=["POST"])
def chat():
    messages = request.json.get("messages", [])

    while True:
        response = client.chat.completions.create(
            model="zai/glm-5.2",
            messages=messages,
            tools=[EXA_TOOL],
            tool_choice="auto",
            temperature=0,
            max_tokens=131072,
        )

        choice = response.choices[0]
        assistant_message = choice.message.model_dump()
        messages.append(assistant_message)

        if choice.finish_reason == "tool_calls":
            for tool_call in choice.message.tool_calls:
                args = json.loads(tool_call.function.arguments)
                results = run_exa_search(
                    query=args["query"],
                    search_type=args["search_type"],
                    summary_query=args["summary_query"],
                    include_domains=args.get("include_domains"),
                    exclude_domains=args.get("exclude_domains"),
                )
                messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": json.dumps(results, ensure_ascii=False)
                })
        else:
            return jsonify({"reply": choice.message.content, "messages": messages})


if __name__ == "__main__":
    app.run(debug=True, port=5000)

